head.script:
// 담당 범위 : maxLength 가이드 중 dataType='float' / 'bigDecimal' 의 정수부·소수부 설정 형식 (Cell 편집 입력으로 확인)
//  - Cell 편집 입력 축(inputType 동작 조건 / 다국어 1문자=1 계산 / editFormat 무시 / maxByteLength 동시 설정)은 column_P_maxLength_1.xml 담당
//  - 스크립트 설정(setCellData + applyMaxLengthOnSetValue)과 붙여넣기 / 드래그 축은 column_P_maxLength_3.xml 담당
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > maxLength]<br/>Column 에 입력할 수 있는 최대 문자 수를 설정합니다.",
    "validation" : [
        "Column 의 dataType='float' 이면 '.' 문자를 기준으로 정수부와 소수부의 최대 자릿수를 나누어 설정할 수 있습니다.",
        "dataType='float' 이고 '5.2' 설정 시, 정수부는 5자리, 소수부는 2자리까지 입력할 수 있습니다.",
        "dataType='float' 이고 '*.2', '.2' 설정 시, 정수부는 제한 없이 입력할 수 있고, 소수부는 2자리까지 입력할 수 있습니다.",
        "dataType='float' 이고 '*', '*.', '.' 설정 시, 정수부만 제한 없이 입력할 수 있습니다.",
        "dataType='float' 이고 '5.*', '5.-1' 설정 시, 정수부는 5자리까지 입력할 수 있고, 소수부는 제한 없이 입력할 수 있습니다.",
        "dataType='float' 이고 '5' 설정 시, 정수부는 5자리까지 입력할 수 있고, 소수부는 입력할 수 없습니다.",
        "Column 의 dataType='bigDecimal' 이면 '5.2' 처럼 숫자로 된 정수부와 소수부 형식으로 설정할 수 있습니다."
    ]
}



// 검증 Column 정보 (id / dataType)
scwin.colInfo = [
    { "id" : "txt", "dataType" : "text" },
    { "id" : "flt", "dataType" : "float" },
    { "id" : "big", "dataType" : "bigDecimal" }
];



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (maxLength 5.2)
    con_maxLength.setValue("5.2");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 검증 Column 3개(txt : dataType=text 대조 / flt : dataType=float / big : dataType=bigDecimal) 모두 inputType=text, maxLength = con_maxLength
//  - 모든 Cell 은 빈 값으로 시작하고, 같은 숫자를 입력해 Column 별 저장값의 정수부 / 소수부 자릿수를 비교한다
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 3개 Column 모두 inputType=text, 같은 maxLength 설정 (txt 는 dataType=text 대조용), 모든 Cell 은 빈 값으로 시작\n[절차] Row 0 의 Cell 더블클릭으로 편집 진입 -> 1234567.123 입력 -> 결과창 클릭으로 편집 종료\n[확인] 편집 종료마다 셀 표시값과 정수부 / 소수부 자릿수 자동 출력"', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue)
    let cMaxLength = con_maxLength.getValue();

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (body column id 와 동일한 컬럼 id 사용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    for (let i = 0; i < scwin.colInfo.length; i++) {
        strDlt += '<w2:column id="' + scwin.colInfo[i].id + '" name="' + scwin.colInfo[i].id + '" dataType="text"></w2:column>';
    }
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "txt" : "", "flt" : "", "big" : "" }
    ], false);

    // 이벤트 바인딩 (편집 종료 시 입력 결과 출력, 값이 바뀌지 않은 경우도 출력되도록 onafteredit 사용)
    let eList = $c.gcm.createEList(["onafteredit"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" defaultCellHeight="30" id="" style="width:600px;height:90px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 0; i < scwin.colInfo.length; i++) {
        strTarget += '<w2:column width="200" style="" inputType="text" id="column' + (i + 1) + '" value="' + scwin.colInfo[i].id + ' (' + scwin.colInfo[i].dataType + ')"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    for (let i = 0; i < scwin.colInfo.length; i++) {
        strTarget += '<w2:column width="200" style="" inputType="text" id="' + scwin.colInfo[i].id + '" value="" dataType="' + scwin.colInfo[i].dataType + '" maxLength="' + cMaxLength + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 적용 설정값 출력
    wf_body_bottom.getObj("scwin").setReturnValue("maxLength : '" + cMaxLength + "'");
}



// validation 1 ~ 7 판정 출력 : 편집 종료 후 셀 표시값과 정수부 / 소수부 자릿수
//  - bigDecimal Column 은 이 환경에서 DataList getCellData 가 null 이라 (column_P_autoDecimalPoint_1.xml 선례) Column 모두 셀 표시값으로 판정한다
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    setTimeout(function () {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_" + columnIndex + "']");
        let cellText = td ? td.textContent : "";
        let arrPart = cellText.split(".");
        let fractionLen = (arrPart.length > 1) ? arrPart[1].length : 0;
        wf_body_bottom.getObj("scwin").setReturnValue(scwin.colInfo[columnIndex].id + " (" + scwin.colInfo[columnIndex].dataType + ") : '" + cellText
            + "' (정수부 " + arrPart[0].length + "자리, 소수부 " + fractionLen + "자리)");
    }, 0);
}
